# Stage SHARE-S4: เอาป้าย "ดูได้อย่างเดียว" ออก · โลโก้ไม่มีขอบขาว (ไฟล์คมขึ้น) · เงาบนรูปพื้นหลังจางลง
#   · เบอร์โทร 092-256-6114 · รองรับลิงก์สั้น (?c=รหัส หรือ /s/รหัส) — ลิงก์ยาว ?t= เดิมยังใช้ได้
import sys

MARK = 'Stage SHARE-S4'
OLD_LOGO = 'data:image/png;base64,'
NEW_LOGO = 'data:image/png;base64,'

CODE_JS = """const CODE = (()=>{ const q=new URLSearchParams(location.search).get('c')||new URLSearchParams(location.hash.slice(1)).get('c')||''; const m=location.pathname.match(/\\/s\\/([0-9A-Za-z]{6,16})\\/?$/); return String(q||(m?m[1]:'')).trim(); })();
// Stage SHARE-S4: ลิงก์สั้น (c) หรือลิงก์ยาวเดิม (t)
const AUTH = /^[0-9a-f]{64}$/.test(TOKEN) ? {t:TOKEN} : (/^[0-9A-Za-z]{6,16}$/.test(CODE) ? {c:CODE} : null);
"""


def rep(s, old, new, path, cnt=1):
    n = s.count(old)
    if n != cnt:
        sys.exit(f'{path}: anchor count {n} != {cnt} for: {old[:80]}')
    return s.replace(old, new)


def patch(path):
    s = open(path, encoding='utf-8').read()
    if MARK in s:
        print(path, ': already patched — skip'); return
    if 'Stage SHARE-S3' not in s:
        sys.exit(path + ': ต้องมี Stage SHARE-S3 ก่อน')
    s = rep(s, '<div class="ro">🔒 ดูได้อย่างเดียว</div>', '', path)
    s = rep(s, OLD_LOGO, NEW_LOGO, path, 2)
    s = rep(s, '.logo img{width:38px;height:38px;border-radius:50%;background:#fff;padding:2px;box-shadow:0 1px 4px rgba(0,0,0,.18);flex:none}',
            '.logo img{width:42px;height:42px;flex:none} /* ' + MARK + ' */', path)
    s = rep(s, 'rgba(20,10,0,.35) 0%,rgba(20,10,0,.62) 100%', 'rgba(20,10,0,.10) 0%,rgba(20,10,0,.42) 100%', path)
    s = rep(s, '<a class="btn-call" href="tel:0968234891">โทร 096-823-4891</a>', '<a class="btn-call" href="tel:0922566114">โทร 092-256-6114</a>', path)
    a = "const TOKEN = (new URLSearchParams(location.search).get('t') || new URLSearchParams(location.hash.slice(1)).get('t') || '').trim().toLowerCase();\n"
    s = rep(s, a, a + CODE_JS, path)
    s = rep(s, "if(!/^[0-9a-f]{64}$/.test(TOKEN)){", "if(!AUTH){", path)
    s = rep(s, "api({t:TOKEN})", "api({...AUTH})", path)
    s = rep(s, "api({t:TOKEN, doc_id:docId})", "api({...AUTH, doc_id:docId})", path)
    open(path, 'w', encoding='utf-8').write(s)
    print(path, ': patched')


for p in sys.argv[1:]:
    patch(p)
